function polylineDistance(P, points, edges, r, k) {
  let d = Infinity;
  for (let i = 0; i < edges.length; i++) {
    const [aIndex, bIndex] = edges[i];
    const next = capsuleDistance(P, points[aIndex], points[bIndex], r);
    d = i === 0 ? next : (k === 0 ? Math.min(d, next) : smoothMin(d, next, k));
  }
  return d;
}
